<?php
require_once __DIR__.'/_init.php';
if(isset($_GET['action'],$_GET['id'])&&in_array($_GET['action'],['approved','rejected','pending'],true)){if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf()){$id=(int)$_GET['id'];$pdo->prepare('UPDATE ds_comments SET status=? WHERE id=?')->execute([$_GET['action'],$id]);log_activity($pdo,'comment_moderation','Mengubah status komentar #'.$id.' menjadi '.$_GET['action'],'comment',$id);$_SESSION['admin_flash']='Status komentar diperbarui.';header('Location: comments.php');exit;}}
$rows=$pdo->query('SELECT c.*,p.title post_title FROM ds_comments c JOIN ds_posts p ON p.id=c.post_id ORDER BY c.created_at DESC')->fetchAll();admin_header('Moderasi Komentar','comments');admin_flash();?>
<div class="admin-panel"><div class="panel-heading"><div><span class="eyebrow">COMMUNITY</span><h2>Komentar pengunjung</h2></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Pengunjung</th><th>Komentar</th><th>Artikel</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['commenter'])?><small class="table-sub"><?=e($r['email'])?></small></td><td><?=e($r['comment_body'])?></td><td><?=e($r['post_title'])?></td><td><?=e($r['status'])?></td><td class="actions"><?php foreach(['approved'=>'Setujui','pending'=>'Pending','rejected'=>'Tolak'] as $v=>$label):?><form method="post" action="comments.php?action=<?=$v?>&id=<?=(int)$r['id']?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button><?=$label?></button></form><?php endforeach;?></td></tr><?php endforeach;?></tbody></table></div></div><?php admin_footer();?>
